function bytes(base64){const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/',out=[];let bits=0,value=0;for(const c of base64){if(c==='=')break;const n=chars.indexOf(c);if(n<0)continue;value=(value<<6)|n;bits+=6;if(bits>=8){bits-=8;out.push((value>>bits)&255);}}return new Uint8Array(out);}
const SCENE_CACHE={};
function sceneKey(s){const k=s.sceneName||s.scene||'farm';return typeof k==='string'&&k.includes('/')?k.split('/').pop().replace(/\.[^.]+$/,''):k;}
function scene(p,s){const key=sceneKey(s);let hash=SCENE_CACHE[key]||BUNDLE.sceneHashes[key];if(hash&&!figma.getImageByHash(hash))hash=null;if(!hash&&BUNDLE.sceneBytes[key])hash=figma.createImage(bytes(BUNDLE.sceneBytes[key])).hash;if(!hash&&BUNDLE.sceneBytes.farm)hash=figma.createImage(bytes(BUNDLE.sceneBytes.farm)).hash;if(hash){SCENE_CACHE[key]=hash;const n=frame(p,'Scene art · '+key,W,H);n.fills=[{type:'IMAGE',imageHash:hash,scaleMode:'FILL'}];n.locked=true;}else fill(p,'primaryTint');}
function worldPlace(s,d={}){const explicit=d.place||(s.navigation?.placeExplicit!==false?s.navigation?.place:null);if(explicit)return explicit;const key=sceneKey(s);if(/^farm/.test(key))return 'Homestead';if(/^pond/.test(key))return 'Willow Pond';if(/^kitchen/.test(key))return 'Kitchen';if(/^mine/.test(key))return 'Mine';if(/^map/.test(key))return 'City map';return ({'tea-house':'Tea House','tackle-shop':'Tackle Shop','market-square-v2':'Market Square','travel-post':'Travel Post','trading-post':'Trading Post'})[key]||'Homestead';}
function hud(p,s){const data={...(s.sceneState||{}),...(s.hud||{})};const n=inst(p,'HUD',{Energy:String(data.energy??142)+'/'+String(data.capacity??200),Coins:String(data.coins??230),Location:[data.city||s.identity?.city||'Shanghai',worldPlace(s,data)].join(' · ')});absolute(n,8,16);return n;}
function panel(p,top){const bg=inst(p,'Sheet',{},360);bg.resize(360,H-top);absolute(bg,0,top);return bg;}
function scroll(p,name,x,y,w,h){const f=frame(p,name,w,h);f.x=x;f.y=y;f.clipsContent=true;f.overflowDirection='VERTICAL';const content=auto(f,'Scrollable content',w,'VERTICAL',12);return {viewport:f,content};}
function tabs(p,s,ownerId){const list=s.tabs||s.navigation?.tabs||[];if(!list.length)return;const view=frame(p,'Tabs · scroll horizontally',p.width,44);view.clipsContent=true;view.overflowDirection='HORIZONTAL';const row=horizontal(view,'Tab list',Math.max(p.width,list.length*100),6);const selected=typeof s.selectedTab==='string'?s.selectedTab:list[s.navigation?.selectedTab||s.selectedTab||0];for(const label of list){const n=inst(row,'Tab',{Label:label},Math.max(80,label.length*7+24));if(label!==selected)fill(n,null);n.name='Tab · '+label;if(label==='Bag'||label==='Gear'){if(label!==selected){const currentContainer=/^(GEAR-P0-|BAG-1-P0)/.test(ownerId||'');PENDING_LINKS.push({node:n,ownerId,action:{label,target:label==='Gear'?(currentContainer?'GEAR-P0-1':'BAG-2'):(currentContainer?'BAG-1-P0':'BAG-1'),kind:'navigate'}});}}else PENDING_LINKS.push({node:n,ownerId,detail:{title:label,state:'Filter',effect:'Items matching '+label.toLowerCase()+'.',items:(s.items||[]).filter(x=>label==='All'||(x.state||'').toLowerCase().includes(label.toLowerCase())||(x.title||'').toLowerCase().includes(label.toLowerCase())),actions:[{label:'Close',kind:'dismiss'}]}});}}
function bottom(p,s,ownerId){const f=auto(p,'Fixed decision area',CW,'VERTICAL',8,'surface');f.paddingTop=12;const actions=(s.actions||[]).filter(a=>a.kind!=='navigate');const commands=actions.filter(a=>a.kind!=='dismiss');if(commands.length){const costs=(s.keyFacts||[]).filter(q=>q.kind==='cost');for(const q of costs)factNode(f,q);const materials=(s.requirements||[]).filter(q=>q.need!==undefined&&!/coin/i.test(q.title||q.label||''));if(materials.length){const txt=materials.map(q=>(q.title||q.label)+' ×'+q.need).join(' · ');text(f,'Uses '+txt,CW,'caption','secondary','Bold');}if(s.supporting)text(f,s.supporting,CW,'body','text','Bold');}let primary=false;for(const a of actions){const isPrimary=!primary&&(a.kind==='commit'||a.kind==='destructive');button(f,a,isPrimary?'primary':'secondary',ownerId);if(isPrimary)primary=true;}if(!actions.length)button(f,{label:'Back',kind:'dismiss'},'secondary',ownerId);const y=H-16-f.height;absolute(f,16,y);return {node:f,y};}
function navAndDetails(p,s,id){for(const a of s.actions||[])if(a.kind==='navigate')button(p,a,'secondary',id);if(s.disclosure?.length){const n=button(p,{label:'Details',kind:'navigate'},'secondary',id);PENDING_LINKS[PENDING_LINKS.length-1].detail={title:s.title,state:'Details',effect:'',disclosure:s.disclosure,actions:[{label:'Close',kind:'dismiss'}]};}}
function content(p,s,id,{header=true,items=true}={}){if(header)heading(p,s);facts(p,(s.keyFacts||[]).filter(x=>x.kind!=='cost'));needs(p,s.requirements,id);if(s.supporting&&!(s.actions||[]).some(a=>['commit','destructive','blocked'].includes(a.kind)))text(p,s.supporting,p.width,'body','text');for(const r of s.rows||[])semanticRow(p,r,id);if(items)for(const r of s.items||[])semanticRow(p,r,id);navAndDetails(p,s,id);}
function grid(p,items,id,{count=25,columns=5,select=true}={}){const width=(p.width-(columns-1)*8)/columns;const rows=auto(p,'Inventory grid · '+columns+' columns',p.width,'VERTICAL',8);const total=Math.max(count,items.length);for(let k=0;k<total;k+=columns){const rr=horizontal(rows,'Inventory row '+(k/columns+1),p.width,8);for(let j=0;j<columns&&k+j<total;j++){const item=items[k+j];const empty=!item||item.title==='Empty';const n=inst(rr,empty?'InventoryCell/empty':item.selected?'InventoryCell/selected':'InventoryCell/default',{Title:item?.title||'',Quantity:item?.quantity?.value||'','Show title':false,'Show quantity':!empty&&Boolean(item?.quantity),'Show icon':!empty,Icon:(ICON[item?.icon]||ICON[inferIcon(item||{})]).id},width);if(!empty&&select)PENDING_LINKS.push({node:n,ownerId:id,detail:{...item,actions:item.actions?.length?item.actions:[{label:'Close',kind:'dismiss'}]}});}}return rows;}
function quickbar(p,s,id){return polishQuickBar(p,s,id,{detailMode:'current',end:'Bag',endAction:{label:'Bag',kind:'navigate',target:'BAG-1-P0'}});}
function inventory(p,s){panel(p,216);const footer=bottom(p,s,s.id);const top=frame(p,'Inventory chrome',328,142);top.x=16;top.y=228;const col=auto(top,'Inventory controls',328,'VERTICAL',8);quickbar(col,s,s.id);const hdr=horizontal(col,'Container identity and capacity',328,8);text(hdr,s.title||'Bag',206,'title','text','ExtraBold');const capacity=(s.keyFacts||[]).find(f=>f.kind==='capacity');text(hdr,capacity?.value||'',114,'body','secondary','Bold');tabs(col,s,s.id);const y=top.y+col.height+12;const body=scroll(p,'Inventory content',16,y,CW,Math.max(100,footer.y-y-12));grid(body.content,s.bagContents||s.items||[],s.id,{count:25});if(s.selectedItem||s.items?.length===1){sectionTitle(body.content,'Selected item');content(body.content,s.selectedItem||s.items[0],s.id,{items:false});}navAndDetails(body.content,s,s.id);}
function gearScreen(p,s){panel(p,216);const foot=bottom(p,s,s.id);const body=scroll(p,'Gear content',16,232,CW,foot.y-244);quickbar(body.content,s,s.id);sectionTitle(body.content,'Tools & Gear');const slots=s.slots||s.items?.slice(0,6)||[];const labels=['Hoe','Rod','Pickaxe','Weapon','Ring','Charm'];const row=horizontal(body.content,'Gear · six slots',328,8);for(let i=0;i<6;i++){const item=slots[i]||{title:labels[i]};const n=inst(row,'GearSlot',{Title:labels[i],Icon:(ICON[item.icon]||ICON[inferIcon(item)]).id},48);PENDING_LINKS.push({node:n,ownerId:s.id,detail:{title:item.title||labels[i],state:item.state||'Gear slot',effect:item.effect||'Choose an owned tool for this slot.',actions:[{label:'Close',kind:'dismiss'}]}});}heading(body.content,s);for(const item of s.rows||[])semanticRow(body.content,item,s.id);for(const item of s.slots?s.items||[]:[])semanticRow(body.content,item,s.id);facts(body.content,s.keyFacts);navAndDetails(body.content,s,s.id);}
function shop(p,s){panel(p,190);const selected=s.selectedItem;const actions=selected?.actions?.length?selected.actions:s.actions;const purchase={...s,actions,keyFacts:[...(s.keyFacts||[]),...(selected?.keyFacts||[])],requirements:selected?.requirements?.length?selected.requirements:s.requirements,supporting:selected?.supporting||s.supporting};const foot=bottom(p,purchase,s.id);const body=scroll(p,'Shop · catalogue and bag',16,208,CW,foot.y-220);heading(body.content,s);tabs(body.content,s,s.id);if(selected){sectionTitle(body.content,'Selected item');heading(body.content,selected);needs(body.content,selected.requirements,s.id);}sectionTitle(body.content,'Catalogue');for(const item of s.items||[])semanticRow(body.content,item,s.id);sectionTitle(body.content,'From your bag');grid(body.content,s.bagContents||s.items||[],s.id,{count:5});navAndDetails(body.content,s,s.id);}
function kitchen(p,s,experiment=false){panel(p,252);const selected=s.selectedItem||s.items?.find(x=>x.actions?.some(a=>a.kind==='commit'))||s.items?.[0];const result={...s,actions:(s.actions||[]).length?s.actions:selected?.actions||[],keyFacts:[...(s.keyFacts||[]),...(selected?.keyFacts||[])],requirements:s.requirements?.length?s.requirements:selected?.requirements||[]};const foot=bottom(p,result,s.id);const pot=frame(p,'Scene stove · selection',44,44,'surface');radius(pot,'pill');absolute(icon(pot,'i-pot',28),8,8);pot.x=158;pot.y=160;PENDING_LINKS.push({node:pot,ownerId:s.id,detail:{title:'Stove',state:'Selected',effect:'Choose a recipe or ingredients below.',actions:[{label:'Close',kind:'dismiss'}]}});const body=scroll(p,'Kitchen · scrollable recipe and ingredients',16,268,CW,foot.y-280);heading(body.content,s);tabs(body.content,s,s.id);if(experiment){sectionTitle(body.content,'Ingredients');const slots=horizontal(body.content,'Ingredient slots',328,10);for(let i=0;i<3;i++){const req=(s.requirements||selected?.requirements||[])[i];const n=inst(slots,req?'NeedTile/met':'NeedTile/short',{Title:req?.title||req?.label||'Add',Value:req?String(req.have??0)+'/'+String(req.need??1):'+',Icon:(ICON[req?.icon]||ICON['i-question']).id},102);PENDING_LINKS.push({node:n,ownerId:s.id,detail:{title:'Choose ingredient',items:s.items||[],actions:[{label:'Close',kind:'dismiss'}]}});}sectionTitle(body.content,'From your bag');grid(body.content,s.items||[],s.id,{count:5});}else{sectionTitle(body.content,'Cookbook');for(const item of s.items||[])semanticRow(body.content,item,s.id);}needs(body.content,result.requirements,s.id);facts(body.content,result.keyFacts.filter(q=>q.kind!=='cost'));navAndDetails(body.content,s,s.id);}
function collection(p,s){panel(p,170);const foot=bottom(p,s,s.id);const body=scroll(p,'Collection grid',16,188,CW,foot.y-200);heading(body.content,s);tabs(body.content,s,s.id);facts(body.content,s.keyFacts);grid(body.content,s.items||[],s.id,{count:s.items?.length||20,columns:4});for(const milestone of s.milestones||[])semanticRow(body.content,milestone,s.id);navAndDetails(body.content,s,s.id);}
function profile(p,s){panel(p,132);const foot=bottom(p,s,s.id);const body=scroll(p,'Profile content',16,148,CW,foot.y-160);const identity=[s.identity?.city,s.identity?.climate,s.identity?.since?'Since '+s.identity.since:''].filter(Boolean).join(' · ');inst(body.content,'ProfileIdentity',{Name:s.title,Identity:identity||s.effect||s.state,Icon:(ICON[s.icon]||ICON['i-face-player']).id});if(s.state)inst(body.content,'StateBadge',{State:s.state});if(s.supporting)text(body.content,s.supporting,CW);facts(body.content,s.keyFacts);if(s.socialCounts)for(const [label,value]of Object.entries(s.socialCounts))factNode(body.content,{label,value:String(value),kind:'progress'});tabs(body.content,s,s.id);for(const item of [...(s.rows||[]),...(s.items||[])])semanticRow(body.content,item,s.id);navAndDetails(body.content,s,s.id);}
function states(p,s){fill(p,'surface');const title=auto(p,'Reference identity',CW);title.x=16;title.y=20;heading(title,s);const y=title.y+title.height+16;const body=scroll(p,'Editable state specimens',16,y,CW,H-y-20);const examples=s.stateExamples?.length?s.stateExamples:[...(s.rows||[]),...(s.items||[])];for(let i=0;i<examples.length;i++){const x=examples[i],box=auto(body.content,'State '+(i+1)+' · '+x.title,CW,'VERTICAL',8,'surfaceRaised');radius(box,'card');content(box,x,s.id);line(body.content);}if(!examples.length)content(body.content,s,s.id,{header:false});if(s.cityTiers){sectionTitle(body.content,'City population tiers');for(const tier of s.cityTiers)semanticRow(body.content,{title:tier.population,effect:tier.outposts},s.id);}if(s.disclosure?.length){sectionTitle(body.content,'Reference');for(const d of s.disclosure)text(body.content,d,CW);}}
function sceneScreen(p,s){const footer=bottom(p,s,s.id);const compact=auto(p,'Scene context',CW,'VERTICAL',8,'surface');compact.x=16;compact.y=122;radius(compact,'card');heading(compact,s);facts(compact,(s.keyFacts||[]).filter(f=>f.kind!=='cost'));if(s.sceneState?.placement){const area=frame(p,'Placement footprint',s.sceneState.footprint===4?144:108,s.sceneState.footprint===4?144:108,'primaryTint');area.opacity=.55;border(area,'primary',2);area.x=(W-area.width)/2;area.y=360;}if(s.sceneState?.stoveStates){const stages=auto(p,'Independent stoves',CW,'VERTICAL',6);stages.x=16;stages.y=Math.max(300,compact.y+compact.height+12);s.sceneState.stoveStates.forEach((v,i)=>semanticRow(stages,{title:'Stove '+(i+1),state:v,icon:'i-pot'},s.id));}if(s.presentation?.feedback==='nonmodal-toast'){const t=inst(p,'Toast',{Message:s.title+' '+s.state.toLowerCase()+'. '+s.effect});absolute(t,16,630);}
 const navigation=(s.actions||[]).filter(a=>a.kind==='navigate');if(navigation.length){const nav=auto(p,'Scene destinations',CW,'VERTICAL',0,'surface');nav.x=16;for(const a of navigation)button(nav,a,'secondary',s.id);nav.y=Math.max(compact.y+compact.height+12,footer.y-nav.height-92);radius(nav,'card');}if(!s.sceneState?.placement&&!['map','kitchen'].includes(sceneKey(s))){const quick=auto(p,'Scene Quick Bar',336);quick.x=12;quick.y=708;quickbar(quick,s,s.id);}if(s.items?.length){const y=compact.y+compact.height+12;const entries=scroll(p,'Scene object entries',16,y,CW,Math.max(80,footer.y-y-88));for(const it of s.items)semanticRow(entries.content,it,s.id);}if(s.disclosure?.length){PENDING_LINKS.push({node:compact,ownerId:s.id,detail:{title:s.title,state:s.state,disclosure:s.disclosure,actions:[{label:'Close',kind:'dismiss'}]}});}}
