function avatarGroupVariants(){if(AVATAR_VIEW.variantSet)return;const variants=Object.values(AVATAR_VIEW.views);if(variants.length!==30)throw Error('Expected all 30 original-layout Avatar variants');const set=figma.combineAsVariants(variants,LIBRARY);set.name='Gensen Refactor/Avatar Wardrobe';set.description='Original upper character preview and lower category tabs + three-column part grid. Actual single-part engine renders, not an arbitrary-combination 3D simulation.';variants.forEach((c,i)=>{c.x=24+(i%5)*384;c.y=24+Math.floor(i/5)*824;});set.resizeWithoutConstraints(1968,Math.ceil(variants.length/5)*824+24);set.x=1400;set.y=450;AVATAR_VIEW.variantSet=set;LEDGER.componentSets.AvatarWardrobe=set.id;LIBRARY.resize(Math.max(LIBRARY.width,3400),Math.max(LIBRARY.height,set.y+set.height+32));}
function avatarResultKeys(){return ['base',...avatarSpec().parts.map(p=>p.id),'defaults'];}
function avatarCreateSaved(ids){for(const key of avatarResultKeys()){if(ids&&!ids.includes(key)||AVATAR_VIEW.saved[key])continue;const saved=avatarFrame('Avatar Profile · '+key);AVATAR_VIEW.saved[key]=saved;avatarSavedComposition(saved,key);LEDGER.overlays[saved.id]={ownerId:'KEEP-P0-1',type:key==='base'?'avatar-original-profile':'avatar-saved-profile',partId:key,actualPreview:true};}}
function avatarCreateContinuations(ids){const spec=avatarSpec();for(const key of avatarResultKeys()){if(ids&&!ids.includes(key)||AVATAR_VIEW.continuations[key])continue;const variant=AVATAR_VIEW.views[key]||AVATAR_VIEW.views.hairhat43,continued=frame(PAGE,'Avatar edit continuation · '+key,360,800,'surface');continued.x=16600+(Object.keys(AVATAR_VIEW.continuations).length%6)*396;continued.y=180+Math.floor(Object.keys(AVATAR_VIEW.continuations).length/6)*880;continued.clipsContent=true;const instance=variant.createInstance();continued.appendChild(instance);absolute(instance,0,0);AVATAR_VIEW.continuations[key]=continued;LEDGER.overlays[continued.id]={ownerId:'KEEP-P0-1',type:'avatar-edit-continuation',partId:key};}}
function avatarWire(){const spec=avatarSpec();for(const edge of AVATAR_VIEW.links){if(edge.wired)continue;if(edge.navigation==='BACK'){STYLE_JOBS.push(edge.node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'BACK'}]}]));edge.wired=true;continue;}const category=edge.category?spec.categories.find(c=>c.slot===edge.category):null,destination=edge.destination||(edge.partId?AVATAR_VIEW.views[edge.partId]:null)||(category?AVATAR_VIEW.views[category.optional?'none-'+category.slot:category.defaultPart]:null)||(edge.savedId?AVATAR_VIEW.saved[edge.savedId]:null)||(edge.continuationId?AVATAR_VIEW.continuations[edge.continuationId]:null);if(!destination)throw Error('Avatar interaction destination is missing');let ancestor=edge.node,self=false;while(ancestor){if(ancestor.id===destination.id){self=true;break}ancestor=ancestor.parent;}if(!self)STYLE_JOBS.push(edge.node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:destination.id,navigation:edge.navigation,transition:null,resetScrollPosition:false,resetInteractiveComponents:Boolean(edge.continuationId)}]}]));edge.wired=true;}LEDGER.avatar=avatarLedger();}
function avatarEnsureLibrary(){if(AVATAR_VIEW.ready)return;avatarCreateThumbnails();avatarMakeTileLibrary();avatarCreateVariants();avatarGroupVariants();avatarCreateSaved();avatarCreateContinuations();avatarWire();AVATAR_VIEW.ready=true;LEDGER.checks.avatar={variants:Object.keys(AVATAR_VIEW.views).length,thumbnails:avatarSpec().parts.length,renderedPreviews:avatarResultKeys().length,saveResults:Object.keys(AVATAR_VIEW.saved).length,base:avatarSpec().base,images:{...AVATAR_VIEW.images},sourceLayout:'scenes/dressing_room/dressing_room.tscn',sourceBehavior:'scenes/dressing_room/dressing_room.gd',prototypeBoundary:avatarSpec().prototypeBoundary};}

function avatarLedger(){const ids=map=>Object.fromEntries(Object.entries(map).map(([key,node])=>[key,node.id]));return {views:ids(AVATAR_VIEW.views),saved:ids(AVATAR_VIEW.saved),continuations:ids(AVATAR_VIEW.continuations),thumbs:ids(AVATAR_VIEW.thumbs),tiles:ids(AVATAR_VIEW.tiles),variantSet:AVATAR_VIEW.variantSet?.id||null,images:{...AVATAR_VIEW.images},links:AVATAR_VIEW.links.map(({node,destination,...rest})=>({...rest,nodeId:node.id,destinationId:destination?.id||null}))};}
