async function currentCompactContainerLibrary(){const collections=await figma.variables.getLocalVariableCollectionsAsync();let collection=collections.find(c=>c.name==='Gensen · P0 Bag filters · Prototype');if(!collection)collection=figma.variables.createVariableCollection('Gensen · P0 Bag filters · Prototype');const vars=await figma.variables.getLocalVariablesAsync();for(const label of POLISH_FILTERS)for(const role of ['active','visible']){const key='p0bag/'+role+'/'+label;let v=vars.find(v=>v.variableCollectionId===collection.id&&v.name===key);if(!v){v=figma.variables.createVariable(key,collection,'BOOLEAN');v.scopes=['ALL_SCOPES'];v.setValueForMode(collection.defaultModeId,role==='visible'||label==='All');v.description='Filters the explicitly authored25-slot Bag fixture; never changes inventory.';}VAR[key]=v;LEDGER.variables[key]=v.id;}}
