function p0ContainerQuick(parent,s){return polishQuickBar(parent,s,s.id,{items:[],end:'Close',detailMode:'item',endAction:{label:'Close',kind:'dismiss'}});}
function p0ContainerShell(p,s){if(s.scene==='farm')containerCamera(p,s);else scene(p,s);hud(p,s);const bg=polishBox(p,'Compact/P0 container drawer',360,546,'surface',20);absolute(bg,0,254);bg.bottomLeftRadius=bg.bottomRightRadius=0;bg.fills=[solid('surface',.97)];const col=auto(p,'Compact/P0 container content',336,'VERTICAL',6);absolute(col,12,266);if(!s.id.startsWith('STORE-'))p0ContainerQuick(col,s);else{const close=inst(p,'Close');absolute(close,304,206);PENDING_LINKS.push({node:close,ownerId:s.id,action:{label:'Close',kind:'dismiss'}});}return col;}
function p0ItemCategory(item){if(item.icon==='i-sprout'||item.title==='Herb')return 'Produce';return containerCategory(item);}
function p0BagFilters(parent,s){const view=frame(parent,'P0 Bag category filters',336,36);view.clipsContent=true;view.overflowDirection='HORIZONTAL';const row=horizontal(view,'Seven categories',390,4);for(const [i,label]of POLISH_FILTERS.entries()){const w=[32,42,32,53,46,63,44][i],tab=frame(row,'Filter · '+label,w,36);inst(tab,'Compact/Filter/default',{Label:label},w);const on=inst(tab,'Compact/Filter/selected',{Label:label},w);on.setBoundVariable('visible',VAR['p0bag/active/'+label]);const actions=[];for(const name of POLISH_FILTERS)for(const role of ['active','visible'])actions.push({type:'SET_VARIABLE',variableId:VAR['p0bag/'+role+'/'+name].id,variableValue:{type:'BOOLEAN',resolvedType:'BOOLEAN',value:role==='active'?name===label:label==='All'||name===label}});STYLE_JOBS.push(tab.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions}]));}}
function p0CompactGrid(parent,items,s,filter=false){const grid=auto(parent,'Compact/P0 inventory grid',336,'HORIZONTAL',6);grid.paddingLeft=26;grid.paddingRight=26;grid.layoutWrap='WRAP';grid.primaryAxisSizingMode='FIXED';grid.counterAxisSizingMode='AUTO';grid.counterAxisSpacing=6;for(const raw of items){const item=legacyItem(raw),cell=inst(grid,'Compact/InventoryCell/'+(item.empty?'empty':item.selected?'selected':'default'),{Icon:legacyGlyph(item.icon),'Show icon':!item.empty,'Show quantity':!item.empty&&Boolean(item.quantity),Quantity:'×'+(item.quantity?.value||''),'Show rarity':false});cell.name='Inventory stack · '+item.title;if(filter)cell.setBoundVariable('visible',VAR['p0bag/'+(item.empty?'active/All':'visible/'+p0ItemCategory(item))]);if(!item.empty)PENDING_LINKS.push({node:cell,ownerId:s.id,detail:{...item,actions:[{label:'Close',kind:'dismiss'}]}});}return grid;}
