const CURRENT_COMPACT_CONTAINER_BASE={library,buildScreen};
library=async function(){await CURRENT_COMPACT_CONTAINER_BASE.library();await currentCompactContainerLibrary();};
buildScreen=function(s,index){if(!CURRENT_COMPACT_CONTAINER_IDS.includes(s.id))return CURRENT_COMPACT_CONTAINER_BASE.buildScreen(s,index);const box=figma.createSection();box.name='Review · '+s.id;PAGE.appendChild(box);box.resizeWithoutConstraints(360,1000);fill(box);box.x=100+(index%8)*412;box.y=180+Math.floor(index/8)*1070;const p=frame(box,s.id+' · '+s.title,360,800,'surface');p.clipsContent=true;currentCompactContainerInto(p,s);reviewNote(box,s,816);LEDGER.screens[s.id]=p.id;LEDGER.sourceReferences[s.id]={newNodeId:p.id,sourceNodeId:s.sourceRef?.nodeId,layout:'compact-p0-container',fixturePreserved:true};return p;};

