 const sourceCast=BUNDLE.screens.find(x=>x.id==='FISH-1')?.actions?.find(a=>a.label==='Cast');PENDING_LINKS.push({node:main,ownerId:s.id,action:full?{label:'Cast',kind:'blocked',feedback:'Creel full. Make room before casting.'}:sourceCast||{label:'Cast',kind:'commit',target:'FISH-2'}});
 const toolHit=frame(screen,'Gear · 44 px touch target',44,44);absolute(toolHit,267,585);const badge=frame(toolHit,'Rod badge',20,20,'surface');radius(badge,10);border(badge);absolute(icon(badge,'i-rod',14),3,3);absolute(badge,12,12);PENDING_LINKS.push({node:toolHit,ownerId:s.id,action:{label:'Gear',kind:'navigate',target:'BAG-2'}});
 const sw=frame(screen,'Action selector · 44 px',44,44);absolute(sw,296,548);const disc=frame(sw,'Action selector visual',32,32,'surface');radius(disc,16);absolute(disc,6,6);absolute(icon(disc,'i-switch',18),7,7);PENDING_LINKS.push({node:sw,ownerId:s.id,action:{label:'Choose action',kind:'navigate',target:'BAR-2'}});
 const bar=auto(screen,'Source fishing Quick Bar',336);absolute(bar,12,708);quickbar(bar,{...s,layout:'scene'},s.id);
