function fishingRecoveryLinks(screen,s){const row=horizontal(screen,'Creel recovery routes',228,8);absolute(row,16,612);const available=(s.actions||[]).filter(a=>a.kind==='navigate'&&['Open Bag','Go home'].includes(a.label));for(const [i,a]of available.entries()){const w=i===0?104:116;const n=frame(row,'Recovery · '+a.label,w,44,'surface');radius(n,'pill');border(n);absolute(text(n,a.label,w-28,'caption','info','Bold'),10,14);absolute(text(n,'›',10,'body','info','Bold'),w-18,11);PENDING_LINKS.push({node:n,ownerId:s.id,action:a});}}
function visualFishingScreen(s,index){const box=figma.createSection();box.name='Review · '+s.id;PAGE.appendChild(box);box.resizeWithoutConstraints(360,1000);fill(box);box.x=100+(index%8)*412;box.y=180+Math.floor(index/8)*1070;const screen=frame(box,s.id+' · '+s.title,W,H,'surface');screen.clipsContent=true;fishingSourceCamera(screen,s);hud(screen,s);fishingCreel(screen,s);fishingSmallAction(screen,s);if(s.id==='FISH-3')fishingCatchCard(screen,s);else fishingRecoveryLinks(screen,s);reviewNote(box,s,816);LEDGER.screens[s.id]=screen.id;LEDGER.sourceReferences[s.id]={sourceNodeId:s.figmaNodeId,newNodeId:screen.id,sourceFile:s.sourceHtml,sourceGroup:s.sourceGroup,layout:s.id==='FISH-3'?'compact-fish-result':'scene-capacity-gate',reviewOnly:false};return screen;}
