function tutorialHeatDetail(detail,ownerId){
  const source=BUNDLE.screens.find(s=>s.id===ownerId);if(!source)throw Error('Tutorial heat needs its source recipe context');
  const n=overlayFrame('Tutorial heat · '+ownerId,H);n.cornerRadius=0;scene(n,source);kitchenPolishCamera(n);polishedKitchenHud(n,source);
  const fish=icon(n,'i-fish',27);absolute(fish,166,175);fish.opacity=.55;
  const master=tutorialHeatMaster(),ring=master.createInstance();n.appendChild(ring);ring.name='First cook · pot heat control';absolute(ring,120,133);PENDING_LINKS.push({node:ring,ownerId,action:{label:'Tap pot in gold',kind:'commit',target:'TUT-3-07C'}});
  const message=auto(n,'Compact/Tutorial heat instruction',304,'VERTICAL',6,'surface');pad(message,12);radius(message,14);absolute(message,28,668);const header=horizontal(message,'Recipe and remaining time',280,8);kitchenPolishText(header,'Grilled Crucian',202,14,'ExtraBold');kitchenPolishText(header,'0:03',70,14,'ExtraBold');kitchenPolishText(message,'Tap the pot when the needle is in gold.',280,12,'Bold');
  LEDGER.overlays[n.id]={title:'First cook · Grilled Crucian',ownerId,type:'tutorial-heat',durationSeconds:5,shownMomentSeconds:2.5,firstGoldWindow:.5,successTarget:'TUT-3-07C'};return n;
}
hud=function(p,s){return s.id==='TUT-3-07B'?polishedKitchenHud(p,s):CURRENT_KITCHEN_FOCUS_BASE.hud(p,s);};
kitchen=function(p,s){return s.id==='TUT-3-07B'?focusedTutorialKitchen(p,s):CURRENT_KITCHEN_FOCUS_BASE.kitchen(p,s);};
createDetail=function(detail,ownerId){return detail.tutorialHeat?tutorialHeatDetail(detail,ownerId):CURRENT_KITCHEN_FOCUS_BASE.createDetail(detail,ownerId);};

/* Unknown inventory is neutral. MCP clone does not preserve parent/property
 * references, so attach the variant and rebind all fields to the existing owner. */
function requirementHasUnknownCount(q){return q.level===undefined&&q.need!==undefined&&q.need!==null&&(q.have===undefined||q.have===null);}
function requirementFields(main){const ring=main.findOne(n=>n.name==='Progress ring');return {ring,title:main.findOne(n=>n.type==='TEXT'&&n.name==='Title'),value:main.findOne(n=>n.type==='TEXT'&&n.name==='Value'),icon:ring?.children.find(n=>n.type==='INSTANCE')};}
function requirementCheckMaster(){
 const met=KIT['NeedTile/met'];if(!met||met.type!=='COMPONENT'||met.parent?.type!=='COMPONENT_SET')throw Error('Existing NeedTile variants required');const set=met.parent,base=requirementFields(met);
 const keys={Title:base.title?.componentPropertyReferences?.characters,Value:base.value?.componentPropertyReferences?.characters,Icon:base.icon?.componentPropertyReferences?.mainComponent};const definitions=set.componentPropertyDefinitions;
 for(const [name,key]of Object.entries(keys))if(!key||!definitions[key]||definitions[key].type!==(name==='Icon'?'INSTANCE_SWAP':'TEXT'))throw Error('Original NeedTile property missing: '+name);
 let check=KIT['NeedTile/check']||set.children.find(n=>n.type==='COMPONENT'&&n.name==='State=check');if(!check)check=met.clone();check.name='State=check';if(check.parent?.id!==set.id)set.appendChild(check);if(check.parent?.id!==set.id)throw Error('Neutral variant has wrong component-property owner');
 const fields=requirementFields(check);if(!fields.ring||!fields.title||!fields.value||!fields.icon)throw Error('Neutral NeedTile layers missing');
 fields.title.componentPropertyReferences={...fields.title.componentPropertyReferences,characters:keys.Title};fields.value.componentPropertyReferences={...fields.value.componentPropertyReferences,characters:keys.Value};fields.icon.componentPropertyReferences={...fields.icon.componentPropertyReferences,mainComponent:keys.Icon};
 border(fields.ring,'border',1);fill(fields.value,'secondary');fields.value.textAutoResize='HEIGHT';
 check.x=met.x;check.y=Math.max(...set.children.filter(n=>n.id!==check.id).map(n=>n.y+n.height))+20;set.resizeWithoutConstraints(Math.max(set.width,check.x+check.width+24),check.y+check.height+24);check.description='Owned quantity has not been checked. Configure Title, Value (Required ×N) and Icon; neutral style never implies that inventory meets the condition.';
 KIT['NeedTile/check']=check;LEDGER.components['NeedTile/check']=check.id;return check;
}
function neutralizeUnknownRequirement(tile,q){
 const master=requirementCheckMaster(),fields=requirementFields(master),keys={Title:fields.title.componentPropertyReferences.characters,Value:fields.value.componentPropertyReferences.characters,Icon:fields.icon.componentPropertyReferences.mainComponent};
 const iconRef=(q.icon&&ICON[q.icon]?.id)||q.iconComponentId;if(!iconRef)throw Error('Explicit requirement source icon is required; do not preserve an already incorrect swap');
 const reactions=JSON.parse(JSON.stringify(tile.reactions));tile.swapComponent(master);tile.name='NeedTile/check';tile.setProperties({[keys.Title]:q.title||q.label||'Requirement',[keys.Value]:'Required ×'+q.need,[keys.Icon]:iconRef});
 const actual=requirementFields(tile);if(actual.title.characters!==(q.title||q.label||'Requirement')||actual.value.characters!=='Required ×'+q.need||actual.icon.mainComponent?.id!==iconRef)throw Error('Neutral requirement property propagation failed');
 fill(actual.value,'secondary');border(actual.ring,'border',1);STYLE_JOBS.push(tile.setReactionsAsync(reactions));return tile;
}
const UNKNOWN_REQUIREMENT_PREVIOUS_NEEDS=needs;
needs=function(p,list,ownerId){const before=new Set(p.children.map(n=>n.id));UNKNOWN_REQUIREMENT_PREVIOUS_NEEDS(p,list,ownerId);if(!list?.some(requirementHasUnknownCount))return;const wrap=p.children.find(n=>!before.has(n.id)&&n.name==='Requirements');if(!wrap)return;const tiles=wrap.children.flatMap(row=>row.children.filter(n=>n.type==='INSTANCE'));list.forEach((q,index)=>{if(requirementHasUnknownCount(q)&&tiles[index])neutralizeUnknownRequirement(tiles[index],q);});};

/* P2/P3 visual QA: let short sheets fit their content and keep controls nearby.
 * Native scene art, typography masters, commands and reactions are preserved.
 * Excludes Avatar, cooking composition, inventory, Gear and nonmodal scene HUDs. */
const P2P3_VISUAL_IDS = new Set(["TRAVEL-GUIDE","TRAVEL-CANCEL","TRAVEL-REFUNDED","DAYPASS","DAYPASS-EXPIRED","PERMIT-1","PERMIT-DONE","TICKET-1","SECOND-HOME","SECOND-HOME-DONE","SOC-1","SOC-1-GATE","SOC-1-CONFIRM","SOC-2","SOC-2-INBOX","SOC-2-ARRIVE","SOC-2-ERROR","SOC-3","HELPER-INBOX","HELPER-SUMMARY","HELPER-ONSITE","HELPER-BUDGET","SOC-5","GIFT-SENT","GIFT-CLAIM","GIFT-DETAIL","SOC-6","GUESTBOOK","TOGETHER","TOGETHER-PROGRESS","TOGETHER-DONE","TRADER","BUFF-FARM","BUFF-FISH","BUFF-HANDS","BUFF-TRAVEL","BUFF-CREEL","BUFF-REPLACE","BUFF-ACTIVE","BUFF-CASTS","BUFF-LAST","BUFF-TIMEOUT","BUFF-RATIONS-USE","BUFF-CREEL-END","HOME-LV4","HOME-LV5","HOME-LV6","HOME-LV7","HOME-LV8","HOME-LV9","HOME-LV10","MINE-3","COMBAT-1","COMBAT-LOOT","COMBAT-HEAL","MINE-4","MINE-5","MINE-KO","RESIDENT-TALK","RESIDENT-CHAT","RESIDENT-MEAL","RESIDENT-MEAL-DONE","RESIDENT-TEACH","RES-PIP","RES-GRANNY","RES-MIRA","RES-KAI","RES-RAFA","RES-IVO","RES-HANA","RES-SAM","RES-LENA","RES-TOMO","RES-THEO","RES-NADIA","DEX-MILESTONE"]);
function p2p3Property(node,name){if(node.type!=='INSTANCE')return null;const key=Object.keys(node.componentProperties||{}).find(k=>k.split('#')[0]===name);return key?node.componentProperties[key].value:null;}
function p2p3VisualRefine(screen,s,force=false){
 if((!force&&!P2P3_VISUAL_IDS.has(s.id))||s.kitchen||s.layout==='scene')return {id:s.id,applied:false,reason:'outside generic sheet scope'};
 const viewport=screen.children.find(n=>['Main content','Profile content'].includes(n.name)),footer=screen.children.find(n=>n.name==='Fixed decision area'),panel=screen.children.find(n=>n.type==='INSTANCE'&&n.name==='Sheet');
 const body=viewport?.children.find(n=>n.name==='Scrollable content');
 if(!viewport||!footer||!panel||!body)return {id:s.id,applied:false,reason:'no generic sheet structure'};
 const before={panelTop:panel.y,viewportHeight:viewport.height,bodyHeight:body.height},changed=new Set();
 if(s.id==='SOC-6')for(const row of body.children){if(row.type==='INSTANCE'&&p2p3Property(row,'Title')==='Guestbook'&&!row.reactions.length){row.visible=false;changed.add(row.id);}}
 body.itemSpacing=8;changed.add(body.id);
 // Use whole content rows when a long list still needs to scroll; a short sheet
 // uses the exact Auto Layout content height and brings its action block near it.
 const maximum=footer.y-168-28,visible=body.children.filter(n=>n.visible!==false&&n.layoutPositioning!=='ABSOLUTE');let running=body.paddingTop||0,lastWhole=0;
 for(let i=0;i<visible.length;i++){const next=running+visible[i].height+(i?body.itemSpacing:0);if(next>maximum)break;running=next;lastWhole=running;}
 const bodyHeight=body.height,visibleHeight=Math.max(120,bodyHeight<=maximum?bodyHeight:(lastWhole||maximum)),top=Math.max(168,footer.y-visibleHeight-28);
 panel.resize(360,800-top);panel.y=top;fill(panel,'surface');changed.add(panel.id);
 viewport.y=top+16;viewport.resize(328,Math.max(120,footer.y-viewport.y-12));changed.add(viewport.id);
 const close=screen.children.find(n=>n.name==='Close · 44 px');if(close){close.y=Math.max(132,top-50);changed.add(close.id);}
 return {id:s.id,applied:true,changedNodeIds:[...changed],before,after:{panelTop:panel.y,viewportHeight:viewport.height,bodyHeight:body.height,scrolls:body.height>viewport.height},footerGap:footer.y-(viewport.y+viewport.height)};
}
const P2P3_VISUAL_PREVIOUS_BUILD=buildScreen;
buildScreen=function(s,index){const screen=P2P3_VISUAL_PREVIOUS_BUILD(s,index);const result=p2p3VisualRefine(screen,s);if(result.applied){LEDGER.checks.p2p3CompactSheets=LEDGER.checks.p2p3CompactSheets||{};LEDGER.checks.p2p3CompactSheets[s.id]=result;}return screen;};

